"""Tests for the pipeline engine (create_pipeline, run_pipeline, get_pipeline_status).

All execution, template loading, and output resolution are mocked.
No ComfyUI server or filesystem access required.
"""

import json
import threading
from unittest.mock import MagicMock, patch, call

import pytest

import agent.tools.pipeline as pipeline_mod
from agent.tools.pipeline import (
    TOOLS,
    _apply_input_mappings,
    _apply_param_overrides,
    _load_workflow_for_stage,
    _validate_pipeline_definition,
    _pipeline_state,
    _pipeline_lock,
    handle,
)


# ---------------------------------------------------------------------------
# Fixtures
# ---------------------------------------------------------------------------

@pytest.fixture(autouse=True)
def reset_pipeline_state():
    """Reset module-level state between every test."""
    with _pipeline_lock:
        _pipeline_state["current_pipeline"] = None
        _pipeline_state["execution_results"] = []
        _pipeline_state["status"] = "idle"
        _pipeline_state["error"] = None
    yield
    # Clean up after test too
    with _pipeline_lock:
        _pipeline_state["current_pipeline"] = None
        _pipeline_state["execution_results"] = []
        _pipeline_state["status"] = "idle"
        _pipeline_state["error"] = None


def _minimal_workflow():
    """Return a minimal API-format workflow dict."""
    return {
        "1": {"class_type": "CheckpointLoaderSimple", "inputs": {"ckpt_name": "sd15.safetensors"}},
        "2": {"class_type": "KSampler", "inputs": {"seed": 42, "steps": 20}},
        "9": {"class_type": "SaveImage", "inputs": {"filename_prefix": "out"}},
    }


def _mock_exec_success(prompt_id="test-prompt-001"):
    """Return a mock successful execution result dict."""
    return {
        "status": "complete",
        "prompt_id": prompt_id,
        "total_time_s": 3.5,
        "outputs": [
            {"type": "image", "filename": "ComfyUI_00001_.png", "subfolder": ""},
        ],
    }


def _mock_resolved_output(filename="ComfyUI_00001_.png"):
    """Return a mock resolved output entry."""
    return {
        "filename": filename,
        "subfolder": "",
        "absolute_path": f"/output/{filename}",
        "exists": True,
        "size_bytes": 2048,
        "type": "image",
    }


def _two_stage_pipeline(name="test_pipe"):
    """Build a minimal two-stage pipeline definition."""
    return {
        "name": name,
        "stages": [
            {"stage_id": "txt2img", "workflow_source": "template:txt2img_sdxl"},
            {"stage_id": "upscale", "workflow_source": "template:upscale_basic"},
        ],
    }


# ---------------------------------------------------------------------------
# TestCreatePipeline
# ---------------------------------------------------------------------------

class TestCreatePipeline:
    def test_create_simple_two_stage(self):
        """Create a pipeline with two stages returns correct summary."""
        result = json.loads(handle("create_pipeline", {
            "name": "my_pipe",
            "stages": [
                {"stage_id": "gen", "workflow_source": "template:txt2img_sdxl"},
                {"stage_id": "upscale", "workflow_source": "template:upscale_basic"},
            ],
        }))
        assert result["created"] is True
        assert result["name"] == "my_pipe"
        assert result["stage_count"] == 2
        assert len(result["stages"]) == 2
        assert result["stages"][0]["stage_id"] == "gen"
        assert result["stages"][1]["stage_id"] == "upscale"
        assert "run_pipeline" in result["message"]

    def test_create_stores_pipeline_in_state(self):
        """Pipeline definition is saved to module state after creation."""
        handle("create_pipeline", {
            "stages": [
                {"stage_id": "stage1", "workflow_source": "template:txt2img_sdxl"},
            ],
        })
        with _pipeline_lock:
            current = _pipeline_state["current_pipeline"]
        assert current is not None
        assert current["stages"][0]["stage_id"] == "stage1"

    def test_create_sets_status_idle(self):
        """Status is reset to idle on create."""
        # Dirty the state first
        with _pipeline_lock:
            _pipeline_state["status"] = "error"
            _pipeline_state["error"] = "previous error"

        handle("create_pipeline", {
            "stages": [
                {"stage_id": "s1", "workflow_source": "template:txt2img_sdxl"},
            ],
        })
        with _pipeline_lock:
            assert _pipeline_state["status"] == "idle"
            assert _pipeline_state["error"] is None
            assert _pipeline_state["execution_results"] == []

    def test_create_with_input_mappings_in_summary(self):
        """Input mappings are reflected in the stage summary."""
        result = json.loads(handle("create_pipeline", {
            "stages": [
                {"stage_id": "gen", "workflow_source": "template:txt2img_sdxl"},
                {
                    "stage_id": "upscale",
                    "workflow_source": "template:upscale_basic",
                    "input_mappings": [
                        {
                            "node_id": "10",
                            "input_name": "image",
                            "from_stage": "gen",
                            "output_index": 0,
                        },
                    ],
                },
            ],
        }))
        assert result["created"] is True
        upscale_summary = result["stages"][1]
        assert "receives_from" in upscale_summary
        assert "gen" in upscale_summary["receives_from"]

    def test_create_with_param_overrides_in_summary(self):
        """param_overrides count is included in stage summary."""
        result = json.loads(handle("create_pipeline", {
            "stages": [
                {
                    "stage_id": "gen",
                    "workflow_source": "template:txt2img_sdxl",
                    "param_overrides": {
                        "3.seed": 99,
                        "6.text": "a beautiful cat",
                    },
                },
            ],
        }))
        assert result["created"] is True
        assert result["stages"][0]["override_count"] == 2

    def test_create_error_empty_stages(self):
        """Empty stages list is rejected."""
        result = json.loads(handle("create_pipeline", {"stages": []}))
        assert "error" in result
        assert "at least one stage" in result["error"].lower()

    def test_create_error_duplicate_stage_ids(self):
        """Duplicate stage_id values are rejected."""
        result = json.loads(handle("create_pipeline", {
            "stages": [
                {"stage_id": "gen", "workflow_source": "template:a"},
                {"stage_id": "gen", "workflow_source": "template:b"},
            ],
        }))
        assert "error" in result
        assert "duplicate" in result["error"].lower()

    def test_create_error_missing_workflow_source(self):
        """Missing workflow_source is rejected."""
        result = json.loads(handle("create_pipeline", {
            "stages": [
                {"stage_id": "gen"},
            ],
        }))
        assert "error" in result
        assert "workflow_source" in result["error"]

    def test_create_error_forward_reference_in_input_mapping(self):
        """Input mapping that references a later stage is rejected."""
        result = json.loads(handle("create_pipeline", {
            "stages": [
                {
                    "stage_id": "gen",
                    "workflow_source": "template:txt2img_sdxl",
                    "input_mappings": [
                        {
                            "node_id": "10",
                            "input_name": "image",
                            "from_stage": "upscale",  # forward reference!
                        },
                    ],
                },
                {"stage_id": "upscale", "workflow_source": "template:upscale_basic"},
            ],
        }))
        assert "error" in result
        assert "upscale" in result["error"]

    def test_create_default_name(self):
        """Pipeline gets a default name when none is specified."""
        result = json.loads(handle("create_pipeline", {
            "stages": [
                {"stage_id": "s1", "workflow_source": "template:txt2img_sdxl"},
            ],
        }))
        assert result["created"] is True
        assert result["name"] == "unnamed_pipeline"

    def test_create_error_missing_stage_id(self):
        """Stage missing stage_id is rejected."""
        result = json.loads(handle("create_pipeline", {
            "stages": [
                {"workflow_source": "template:txt2img_sdxl"},
            ],
        }))
        assert "error" in result
        assert "stage_id" in result["error"]


# ---------------------------------------------------------------------------
# TestRunPipeline
# ---------------------------------------------------------------------------

class TestRunPipeline:
    @patch("agent.tools.pipeline._resolve_stage_outputs")
    @patch("agent.tools.pipeline._execute_stage_workflow")
    @patch("agent.tools.pipeline._load_workflow_for_stage")
    def test_run_two_stage_success(self, mock_load, mock_exec, mock_resolve):
        """Successfully run a two-stage pipeline."""
        mock_load.return_value = (_minimal_workflow(), None)
        mock_exec.return_value = _mock_exec_success()
        mock_resolve.return_value = [_mock_resolved_output()]

        handle("create_pipeline", _two_stage_pipeline()["stages"] and {
            "name": "test_pipe",
            "stages": _two_stage_pipeline()["stages"],
        })

        with patch("agent.tools.pipeline.handle") as mock_dispatch:
            mock_dispatch.return_value = json.dumps({"recorded": True})
            # run using state from create
            result = json.loads(pipeline_mod._handle_run_pipeline({}))

        assert result["status"] == "complete"
        assert result["stages_total"] == 2
        assert result["stages_completed"] == 2
        assert result["stages_failed"] == 0
        assert len(result["stage_results"]) == 2
        assert result["stage_results"][0]["status"] == "complete"
        assert result["stage_results"][1]["status"] == "complete"

    @patch("agent.tools.pipeline._resolve_stage_outputs")
    @patch("agent.tools.pipeline._execute_stage_workflow")
    @patch("agent.tools.pipeline._load_workflow_for_stage")
    def test_run_with_inline_pipeline(self, mock_load, mock_exec, mock_resolve):
        """run_pipeline accepts an inline pipeline definition."""
        mock_load.return_value = (_minimal_workflow(), None)
        mock_exec.return_value = _mock_exec_success()
        mock_resolve.return_value = [_mock_resolved_output()]

        inline = {
            "name": "inline_pipe",
            "stages": [
                {"stage_id": "gen", "workflow_source": "template:txt2img_sdxl"},
            ],
        }
        with patch("agent.tools.pipeline.handle") as mock_dispatch:
            mock_dispatch.return_value = json.dumps({"recorded": True})
            result = json.loads(handle("run_pipeline", {"pipeline": inline}))

        assert result["status"] == "complete"
        assert result["pipeline"] == "inline_pipe"

    def test_run_no_pipeline_error(self):
        """run_pipeline with no state and no inline pipeline returns error."""
        result = json.loads(handle("run_pipeline", {}))
        assert "error" in result
        assert "create_pipeline" in result["error"]

    @patch("agent.tools.pipeline._resolve_stage_outputs")
    @patch("agent.tools.pipeline._execute_stage_workflow")
    @patch("agent.tools.pipeline._load_workflow_for_stage")
    def test_run_stop_on_error_true(self, mock_load, mock_exec, mock_resolve):
        """stop_on_error=True halts pipeline after first stage failure."""
        # First call loads OK, second load fails
        mock_load.side_effect = [
            (None, "Template not found: bad_template"),
            (_minimal_workflow(), None),
        ]
        mock_exec.return_value = _mock_exec_success()
        mock_resolve.return_value = [_mock_resolved_output()]

        pipeline = {
            "name": "stop_test",
            "stages": [
                {"stage_id": "s1", "workflow_source": "template:bad_template"},
                {"stage_id": "s2", "workflow_source": "template:txt2img_sdxl"},
            ],
        }
        with patch("agent.tools.pipeline.handle") as mock_dispatch:
            mock_dispatch.return_value = json.dumps({"recorded": True})
            result = json.loads(handle("run_pipeline", {
                "pipeline": pipeline,
                "stop_on_error": True,
            }))

        assert result["status"] == "error"
        assert result["stages_completed"] == 0
        assert result["stages_failed"] == 1
        # Only one stage result — second stage was never started
        assert len(result["stage_results"]) == 1

    @patch("agent.tools.pipeline._resolve_stage_outputs")
    @patch("agent.tools.pipeline._execute_stage_workflow")
    @patch("agent.tools.pipeline._load_workflow_for_stage")
    def test_run_stop_on_error_false_continues(self, mock_load, mock_exec, mock_resolve):
        """stop_on_error=False continues to subsequent stages after failure."""
        mock_load.side_effect = [
            (None, "Template not found"),   # stage 1 fails
            (_minimal_workflow(), None),     # stage 2 succeeds
        ]
        mock_exec.return_value = _mock_exec_success()
        mock_resolve.return_value = [_mock_resolved_output()]

        pipeline = {
            "name": "continue_test",
            "stages": [
                {"stage_id": "s1", "workflow_source": "template:bad"},
                {"stage_id": "s2", "workflow_source": "template:txt2img_sdxl"},
            ],
        }
        with patch("agent.tools.pipeline.handle") as mock_dispatch:
            mock_dispatch.return_value = json.dumps({"recorded": True})
            result = json.loads(handle("run_pipeline", {
                "pipeline": pipeline,
                "stop_on_error": False,
            }))

        assert result["stages_completed"] == 1
        assert result["stages_failed"] == 1
        assert len(result["stage_results"]) == 2
        assert result["stage_results"][0]["status"] == "error"
        assert result["stage_results"][1]["status"] == "complete"

    @patch("agent.tools.pipeline._resolve_stage_outputs")
    @patch("agent.tools.pipeline._execute_stage_workflow")
    @patch("agent.tools.pipeline._load_workflow_for_stage")
    def test_run_stage_timeout(self, mock_load, mock_exec, mock_resolve):
        """Timed-out stage is recorded as timeout status."""
        mock_load.return_value = (_minimal_workflow(), None)
        mock_exec.return_value = {
            "status": "timeout",
            "prompt_id": "timed-out-123",
            "outputs": [],
        }
        mock_resolve.return_value = []

        pipeline = {
            "name": "timeout_test",
            "stages": [
                {"stage_id": "slow", "workflow_source": "template:txt2img_sdxl"},
            ],
        }
        with patch("agent.tools.pipeline.handle") as mock_dispatch:
            mock_dispatch.return_value = json.dumps({"recorded": True})
            result = json.loads(handle("run_pipeline", {
                "pipeline": pipeline,
                "timeout_per_stage": 30,
            }))

        assert result["status"] == "error"
        assert result["stage_results"][0]["status"] == "timeout"
        assert "30" in result["stage_results"][0]["errors"][0]

    @patch("agent.tools.pipeline._resolve_stage_outputs")
    @patch("agent.tools.pipeline._execute_stage_workflow")
    @patch("agent.tools.pipeline._load_workflow_for_stage")
    def test_run_with_param_overrides_applied(self, mock_load, mock_exec, mock_resolve):
        """param_overrides are applied to workflow before execution."""
        wf = {
            "3": {"class_type": "KSampler", "inputs": {"seed": 0, "steps": 20}},
            "6": {"class_type": "CLIPTextEncode", "inputs": {"text": "default"}},
        }
        mock_load.return_value = (wf, None)
        mock_exec.return_value = _mock_exec_success()
        mock_resolve.return_value = [_mock_resolved_output()]

        pipeline = {
            "name": "override_test",
            "stages": [
                {
                    "stage_id": "gen",
                    "workflow_source": "template:txt2img_sdxl",
                    "param_overrides": {"3.seed": 999, "6.text": "a cat"},
                },
            ],
        }
        with patch("agent.tools.pipeline.handle") as mock_dispatch:
            mock_dispatch.return_value = json.dumps({"recorded": True})
            result = json.loads(handle("run_pipeline", {"pipeline": pipeline}))

        # Verify exec was called with modified workflow
        called_workflow = mock_exec.call_args[0][0]
        assert called_workflow["3"]["inputs"]["seed"] == 999
        assert called_workflow["6"]["inputs"]["text"] == "a cat"
        assert result["status"] == "complete"

    @patch("agent.tools.pipeline._resolve_stage_outputs")
    @patch("agent.tools.pipeline._execute_stage_workflow")
    @patch("agent.tools.pipeline._load_workflow_for_stage")
    def test_run_with_input_mappings_wiring(self, mock_load, mock_exec, mock_resolve):
        """Input mappings wire stage-1 output filename into stage-2 node input."""
        wf_stage1 = {
            "9": {"class_type": "SaveImage", "inputs": {}},
        }
        wf_stage2 = {
            "10": {"class_type": "LoadImage", "inputs": {"image": "default.png"}},
            "11": {"class_type": "UpscaleImage", "inputs": {}},
        }
        mock_load.side_effect = [(wf_stage1, None), (wf_stage2, None)]
        mock_exec.return_value = _mock_exec_success()
        mock_resolve.side_effect = [
            [_mock_resolved_output("stage1_out.png")],
            [_mock_resolved_output("stage2_out.png")],
        ]

        pipeline = {
            "name": "wiring_test",
            "stages": [
                {"stage_id": "gen", "workflow_source": "template:txt2img_sdxl"},
                {
                    "stage_id": "upscale",
                    "workflow_source": "template:upscale_basic",
                    "input_mappings": [
                        {
                            "node_id": "10",
                            "input_name": "image",
                            "from_stage": "gen",
                            "output_index": 0,
                        },
                    ],
                },
            ],
        }
        with patch("agent.tools.pipeline.handle") as mock_dispatch:
            mock_dispatch.return_value = json.dumps({"recorded": True})
            result = json.loads(handle("run_pipeline", {"pipeline": pipeline}))

        # Second exec call should have wired filename into LoadImage
        calls = mock_exec.call_args_list
        stage2_workflow = calls[1][0][0]
        assert stage2_workflow["10"]["inputs"]["image"] == "stage1_out.png"
        assert result["status"] == "complete"

    @patch("agent.tools.pipeline._resolve_stage_outputs")
    @patch("agent.tools.pipeline._execute_stage_workflow")
    @patch("agent.tools.pipeline._load_workflow_for_stage")
    def test_run_exec_error_recorded(self, mock_load, mock_exec, mock_resolve):
        """Execution error from ComfyUI is captured in stage result."""
        mock_load.return_value = (_minimal_workflow(), None)
        mock_exec.return_value = {
            "error": "ComfyUI execution failed: node error",
            "outputs": [],
        }
        mock_resolve.return_value = []

        pipeline = {
            "name": "exec_err_test",
            "stages": [
                {"stage_id": "gen", "workflow_source": "template:txt2img_sdxl"},
            ],
        }
        with patch("agent.tools.pipeline.handle") as mock_dispatch:
            mock_dispatch.return_value = json.dumps({"recorded": True})
            result = json.loads(handle("run_pipeline", {"pipeline": pipeline}))

        assert result["status"] == "error"
        assert result["stage_results"][0]["status"] == "error"
        assert "ComfyUI execution failed" in result["stage_results"][0]["errors"][0]

    @patch("agent.tools.pipeline._resolve_stage_outputs")
    @patch("agent.tools.pipeline._execute_stage_workflow")
    @patch("agent.tools.pipeline._load_workflow_for_stage")
    def test_run_final_outputs_from_last_successful(self, mock_load, mock_exec, mock_resolve):
        """final_outputs contain the outputs of the last successful stage."""
        mock_load.return_value = (_minimal_workflow(), None)
        mock_exec.return_value = _mock_exec_success()
        mock_resolve.side_effect = [
            [_mock_resolved_output("stage1.png")],
            [_mock_resolved_output("stage2_final.png")],
        ]

        pipeline = {
            "name": "final_out_test",
            "stages": [
                {"stage_id": "s1", "workflow_source": "template:a"},
                {"stage_id": "s2", "workflow_source": "template:b"},
            ],
        }
        with patch("agent.tools.pipeline.handle") as mock_dispatch:
            mock_dispatch.return_value = json.dumps({"recorded": True})
            result = json.loads(handle("run_pipeline", {"pipeline": pipeline}))

        assert result["final_outputs"][0]["filename"] == "stage2_final.png"

    @patch("agent.tools.pipeline._resolve_stage_outputs")
    @patch("agent.tools.pipeline._execute_stage_workflow")
    @patch("agent.tools.pipeline._load_workflow_for_stage")
    def test_run_updates_module_status_to_complete(self, mock_load, mock_exec, mock_resolve):
        """Module state status is set to 'complete' after a successful run."""
        mock_load.return_value = (_minimal_workflow(), None)
        mock_exec.return_value = _mock_exec_success()
        mock_resolve.return_value = [_mock_resolved_output()]

        pipeline = {
            "name": "status_test",
            "stages": [{"stage_id": "s1", "workflow_source": "template:a"}],
        }
        with patch("agent.tools.pipeline.handle") as mock_dispatch:
            mock_dispatch.return_value = json.dumps({"recorded": True})
            handle("run_pipeline", {"pipeline": pipeline})

        with _pipeline_lock:
            assert _pipeline_state["status"] == "complete"

    @patch("agent.tools.pipeline._resolve_stage_outputs")
    @patch("agent.tools.pipeline._execute_stage_workflow")
    @patch("agent.tools.pipeline._load_workflow_for_stage")
    def test_run_updates_module_status_to_error_on_failure(
        self, mock_load, mock_exec, mock_resolve
    ):
        """Module state status is set to 'error' after a pipeline failure."""
        mock_load.return_value = (None, "not found")

        pipeline = {
            "name": "fail_test",
            "stages": [{"stage_id": "s1", "workflow_source": "template:bad"}],
        }
        with patch("agent.tools.pipeline.handle") as mock_dispatch:
            mock_dispatch.return_value = json.dumps({"recorded": True})
            handle("run_pipeline", {"pipeline": pipeline})

        with _pipeline_lock:
            assert _pipeline_state["status"] == "error"
            assert _pipeline_state["error"] is not None

    @patch("agent.tools.pipeline._resolve_stage_outputs")
    @patch("agent.tools.pipeline._execute_stage_workflow")
    @patch("agent.tools.pipeline._load_workflow_for_stage")
    def test_run_outcome_recorded_flag(self, mock_load, mock_exec, mock_resolve):
        """outcome_recorded is True when memory dispatch succeeds."""
        mock_load.return_value = (_minimal_workflow(), None)
        mock_exec.return_value = _mock_exec_success()
        mock_resolve.return_value = [_mock_resolved_output()]

        pipeline = {
            "name": "record_test",
            "stages": [{"stage_id": "s1", "workflow_source": "template:a"}],
        }
        with patch("agent.tools.pipeline.handle") as mock_dispatch:
            mock_dispatch.return_value = json.dumps({"recorded": True})
            result = json.loads(pipeline_mod._handle_run_pipeline({"pipeline": pipeline}))

        assert result["outcome_recorded"] is True

    @patch("agent.tools.pipeline._resolve_stage_outputs")
    @patch("agent.tools.pipeline._execute_stage_workflow")
    @patch("agent.tools.pipeline._load_workflow_for_stage")
    def test_run_outcome_not_recorded_on_dispatch_exception(
        self, mock_load, mock_exec, mock_resolve
    ):
        """outcome_recorded is False when memory dispatch raises."""
        mock_load.return_value = (_minimal_workflow(), None)
        mock_exec.return_value = _mock_exec_success()
        mock_resolve.return_value = [_mock_resolved_output()]

        pipeline = {
            "name": "no_record_test",
            "stages": [{"stage_id": "s1", "workflow_source": "template:a"}],
        }
        with patch("agent.tools.pipeline.handle", side_effect=RuntimeError("dispatch fail")):
            result = json.loads(pipeline_mod._handle_run_pipeline({"pipeline": pipeline}))

        assert result["outcome_recorded"] is False

    def test_run_invalid_inline_pipeline_rejected(self):
        """An inline pipeline with invalid definition is rejected."""
        result = json.loads(handle("run_pipeline", {
            "pipeline": {"stages": []},
        }))
        assert "error" in result


# ---------------------------------------------------------------------------
# TestPipelineStatus
# ---------------------------------------------------------------------------

class TestPipelineStatus:
    def test_status_no_pipeline(self):
        """Returns no_pipeline status when nothing has been created."""
        result = json.loads(handle("get_pipeline_status", {}))
        assert result["status"] == "no_pipeline"
        assert "create_pipeline" in result["message"]

    def test_status_after_create_is_idle(self):
        """After create_pipeline, status is idle."""
        handle("create_pipeline", {
            "name": "status_pipe",
            "stages": [
                {"stage_id": "s1", "workflow_source": "template:txt2img_sdxl"},
            ],
        })
        result = json.loads(handle("get_pipeline_status", {}))
        assert result["status"] == "idle"
        assert result["pipeline_name"] == "status_pipe"
        assert result["stages_total"] == 1
        assert result["stages_completed"] == 0
        assert result["stages_failed"] == 0

    @patch("agent.tools.pipeline._resolve_stage_outputs")
    @patch("agent.tools.pipeline._execute_stage_workflow")
    @patch("agent.tools.pipeline._load_workflow_for_stage")
    def test_status_after_successful_run(self, mock_load, mock_exec, mock_resolve):
